package selfupdate

import "golang.org/x/sys/windows/registry"

// Keep the application id and registry view in sync with viva.toml and the
// installer generated by Viva's tools/winpkg (SetRegView 64).
const windowsUninstallKey = `Software\Microsoft\Windows\CurrentVersion\Uninstall\dev.motty.app`

func windowsInstallDirs() (user, machine string) {
	read := func(root registry.Key) string {
		key, err := registry.OpenKey(root, windowsUninstallKey, registry.QUERY_VALUE|registry.WOW64_64KEY)
		if err != nil {
			return ""
		}
		defer key.Close()
		dir, _, err := key.GetStringValue("InstallLocation")
		if err != nil {
			return ""
		}
		return dir
	}
	return read(registry.CURRENT_USER), read(registry.LOCAL_MACHINE)
}
